INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7693924, 1261358, 4008, '<td valign="top">Might be with two light sources but this is not really visible in the image. Overall very soft and flat light. Attractive colours though and I like how you have included the green stem as a background.</td>', 'Might be with two light sources but this is not really visible in the image. Overall very soft and flat light. Attractive colours though and I like how you have included the green stem as a background.', '2021-05-10 04:46:06.000000', NULL, 1),
(7693930, 1261349, 4008, '<td valign="top">Lovely collection of items and nice subdued colours. I think the light source from the left could have been much softer. Especially on the lower left egg this is visible. The shadow is in the middle of the egg, which looks strange.</td>', 'Lovely collection of items and nice subdued colours. I think the light source from the left could have been much softer. Especially on the lower left egg this is visible. The shadow is in the middle of the egg, which looks strange.', '2021-05-10 05:22:28.000000', NULL, 1),
(7693932, 1261348, 4008, '<td valign="top">Nice simple still life with lovely soft colours. I find it quite busy though, both in background and in the reflections. It could also do with a bit of rotation counter clockwise (the background looks fine now but the vase is tilted)</td>', 'Nice simple still life with lovely soft colours. I find it quite busy though, both in background and in the reflections. It could also do with a bit of rotation counter clockwise (the background looks fine now but the vase is tilted)', '2021-05-10 05:23:24.000000', NULL, 1),
(7693936, 1261278, 4008, '<td valign="top">The main light is extremely soft with almost no shadows, it makes the whole scene very flat. The candle feels out of place. It does not really contribute to the lighting of the scene and jumps out because of the different colour temperature.</td>', 'The main light is extremely soft with almost no shadows, it makes the whole scene very flat. The candle feels out of place. It does not really contribute to the lighting of the scene and jumps out because of the different colour temperature.', '2021-05-10 05:36:18.000000', NULL, 1),
(7693938, 1261353, 4008, '<td valign="top">I like the metal look and the depth of the image.</td>', 'I like the metal look and the depth of the image.', '2021-05-10 05:40:12.000000', NULL, 1),
(7693939, 1261359, 4008, '<td valign="top">Very special cactus with nice colours. The second light source is hard to detect, probably only fills in the shadows? That is not a bad point, in many images the second light source makes it worse, here it does not.</td>', 'Very special cactus with nice colours. The second light source is hard to detect, probably only fills in the shadows? That is not a bad point, in many images the second light source makes it worse, here it does not.', '2021-05-10 05:42:46.000000', NULL, 1),
(7693940, 1261351, 4008, '<td valign="top">What happened to the eye? Too much dodging in post processing? I would have expected the head of the horse to be in focus. Focus is now on the trees. Not a very attractive image to me.</td>', 'What happened to the eye? Too much dodging in post processing? I would have expected the head of the horse to be in focus. Focus is now on the trees. Not a very attractive image to me.', '2021-05-10 05:46:25.000000', NULL, 1),
(7693941, 1261355, 4008, '<td valign="top">Nice simple approach but the second light source actually makes the image worse in my view. Two strong light sources from opposite directions hardly ever works to make attractive shapes.</td>', 'Nice simple approach but the second light source actually makes the image worse in my view. Two strong light sources from opposite directions hardly ever works to make attractive shapes.', '2021-05-10 05:48:31.000000', NULL, 1),
(7693942, 1261120, 4008, '<td valign="top">Nice simple scene and soft light, still with enough shadow. The tint underneath the bench is rather cool (i.e. too blue, too cold)</td>', 'Nice simple scene and soft light, still with enough shadow. The tint underneath the bench is rather cool (i.e. too blue, too cold)', '2021-05-10 05:49:59.000000', NULL, 1),
(7693946, 1261350, 4008, '<td valign="top">Taking such a busy object and then two strong light sources almost from opposite directions does not make it very attractive in my view. Far too many highlights and shadows creating confusing shapes. A nice soft light from one side and a very subtle  reflection from the other side or the front would have worked much better.</td>', 'Taking such a busy object and then two strong light sources almost from opposite directions does not make it very attractive in my view. Far too many highlights and shadows creating confusing shapes. A nice soft light from one side and a very subtle  reflection from the other side or the front would have worked much better.', '2021-05-10 06:00:19.000000', NULL, 1),
(7693947, 1261256, 4008, '<td valign="top">Simple and effective. The reflection of the back wall adds enough light to separate the onion from the background. One of the images in the challenge where the second light source does not make the image worse. Good. The more I look at it the more I like it.</td>', 'Simple and effective. The reflection of the back wall adds enough light to separate the onion from the background. One of the images in the challenge where the second light source does not make the image worse. Good. The more I look at it the more I like it.', '2021-05-10 06:00:51.000000', NULL, 1),
(7693952, 1261345, 4008, '<td valign="top">I see great soft colours and a lovely light from the back right that softly strikes across the objects. It creates a great atmosphere and depth. The second light source is behind the glass vase? Hard to see where it is coming from, but it creates some distracting lights in the foreground. I would have cropped the image just across the bottom of the fan to make it more balanced (that would raise my score with 2 points at least). I find the foreground too busy and distracting.</td>', 'I see great soft colours and a lovely light from the back right that softly strikes across the objects. It creates a great atmosphere and depth. The second light source is behind the glass vase? Hard to see where it is coming from, but it creates some distracting lights in the foreground. I would have cropped the image just across the bottom of the fan to make it more balanced (that would raise my score with 2 points at least). I find the foreground too busy and distracting.', '2021-05-10 06:06:23.000000', NULL, 1),
(7693953, 1261327, 4008, '<td valign="top">The light from the right is nice and soft and brings out the shape of the apple. The light from the left is much too strong and hard and creates a distracting spot. Would have been better if it would have been a very small strip of light just emphasising the edge.</td>', 'The light from the right is nice and soft and brings out the shape of the apple. The light from the left is much too strong and hard and creates a distracting spot. Would have been better if it would have been a very small strip of light just emphasising the edge.', '2021-05-10 06:07:49.000000', NULL, 1),
(7693987, 1261189, 86447, '<td valign="top">Hahahahaha!</td>', 'Hahahahaha!', '2021-05-10 12:35:44.000000', NULL, 1),
(7693988, 1261327, 86447, '<td valign="top">Simple and beautiful</td>', 'Simple and beautiful', '2021-05-10 12:36:00.000000', NULL, 1),
(7693989, 1261289, 86447, '<td valign="top">Not sure a "still life" has anything moving in it, but this is fun.</td>', 'Not sure a "still life" has anything moving in it, but this is fun.', '2021-05-10 12:37:09.000000', NULL, 1),
